{
  "technical_and_design_decisions": [
    "Implementation will follow existing patterns in the fabric-config library (Go language).",
    "For U2, the ConfigUpdateEnvelope will be returned without signatures, allowing external signing via peer CLI.",
    "For U3 and U4, removal functions will be idempotent and only remove the specific legacy fields (OrdererAddresses, KafkaBrokers).",
    "For U5, consenter removal will match all four fields (host, port, client_tls_cert, server_tls_cert) for safety.",
    "U6 CLI tool will be implemented as a new command in the existing configtx CLI, using Fabric SDK Go for peer/orderer communication and discovery service.",
    "U6 will support the exact JSON structures specified for batch operations, connection profile, and signing identities.",
    "U7 and U8 will add granular setter methods that preserve existing configuration values, consistent with existing API style (e.g., AddCapability).",
    "Certificate validation will be performed where necessary (e.g., MSP cert additions).",
    "Examples will be updated in the same repository to demonstrate new APIs and CLI usage.",
    "Unit tests will be written for all new functions; integration tests for CLI tool using a test network."
  ],
  "assumptions": [
    "Codebase is in Go and follows existing fabric-config library structure.",
    "Existing test infrastructure (unit/integration) can be extended.",
    "Examples reside in the same repository and are updated as part of each story.",
    "CLI tool uses Fabric SDK Go for discovery service and transaction submission.",
    "Connection profile format follows Hyperledger Fabric 2.0 specification.",
    "Signing identities JSON format matches the provided example.",
    "Bulk operations JSON format matches the provided batchUpdate.json structure.",
    "Developer is familiar with Hyperledger Fabric architecture and the fabric-config library.",
    "Effort estimates include coding, unit tests, example updates, and code review preparation but not code review time itself.",
    "No major refactoring of existing code is required beyond adding new functions."
  ],
  "activities": [
    {
      "activity_id": "A1.1",
      "activity_name": "Design API for AddConsortium",
      "activity_description": "Define function signature, error handling, and integration with consortiums group for U1.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A1.2",
      "activity_name": "Implement AddConsortium function",
      "activity_description": "Add function to create new consortium in configtx library, handle empty orgs case.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A1.3",
      "activity_name": "Write unit tests for AddConsortium",
      "activity_description": "Cover normal and edge cases (e.g., no orgs added).",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A1.4",
      "activity_name": "Update examples for consortium addition",
      "activity_description": "Modify examples to demonstrate adding consortium and orgs.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A1.5",
      "activity_name": "Integration test for consortium addition",
      "activity_description": "Test with a simple network to verify config update works end-to-end.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2.1",
      "activity_name": "Design API for unsigned ConfigUpdateEnvelope",
      "activity_description": "Define function to return cb.ConfigUpdateEnvelope without requiring signing identities for U2.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A2.2",
      "activity_name": "Implement unsigned ConfigUpdateEnvelope function",
      "activity_description": "Add function that generates envelope without signatures.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2.3",
      "activity_name": "Write unit tests for unsigned envelope",
      "activity_description": "Verify envelope structure and absence of signatures.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2.4",
      "activity_name": "Update examples for unsigned envelope",
      "activity_description": "Show usage of new function in examples.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A3.1",
      "activity_name": "Design API for RemoveLegacyOrdererAddresses",
      "activity_description": "Define function to remove top-level OrdererAddresses field for U3.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A3.2",
      "activity_name": "Implement RemoveLegacyOrdererAddresses",
      "activity_description": "Add function to channel group to remove legacy field, ensure it cannot be updated.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A3.3",
      "activity_name": "Write unit tests for RemoveLegacyOrdererAddresses",
      "activity_description": "Test removal and verify field is gone.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A3.4",
      "activity_name": "Update examples for legacy orderer removal",
      "activity_description": "Demonstrate migration from 1.0 channel config.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A4.1",
      "activity_name": "Design API for RemoveKafkaBrokers",
      "activity_description": "Define function to remove KafkaBrokers section for U4.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A4.2",
      "activity_name": "Implement RemoveKafkaBrokers",
      "activity_description": "Add function to remove KafkaBrokers from config, similar to RemoveLegacyOrdererAddresses.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A4.3",
      "activity_name": "Write unit tests for RemoveKafkaBrokers",
      "activity_description": "Test removal and ensure consenter type is etcdraft.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A4.4",
      "activity_name": "Update/improve Kafka to EtcdRaft migration example",
      "activity_description": "Enhance example to demonstrate full migration including KafkaBrokers removal.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A5.1",
      "activity_name": "Design API for Add/Remove Consenters",
      "activity_description": "Define functions for etcdraft consenter management matching four fields for U5.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A5.2",
      "activity_name": "Implement AddConsenter and RemoveConsenter",
      "activity_description": "Add functions to etcdraft orderer configuration, removal matches host, port, client_tls_cert, server_tls_cert.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A5.3",
      "activity_name": "Write unit tests for consenter management",
      "activity_description": "Test add/remove with various field combinations.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A5.4",
      "activity_name": "Update examples for consenter management",
      "activity_description": "Show usage similar to orderer endpoints and anchor peers.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A6.1",
      "activity_name": "Design CLI command structure and flags",
      "activity_description": "Define command line interface for bulk operations, including --dryrun flag for U6.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A6.2",
      "activity_name": "Implement JSON parsing for input files",
      "activity_description": "Parse batchUpdate.json, connectionProfile.json, signingIdentities.json with validation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6.3",
      "activity_name": "Implement connection profile and discovery service integration",
      "activity_description": "Use Fabric SDK Go to connect to peer, fetch config blocks via discovery service.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6.4",
      "activity_name": "Implement config update operations (MSP, Consenters, Anchor Peers)",
      "activity_description": "Support REPLACE, DELETE, UPDATE, ADD for MSP admins, TLS certs, consenters, anchor peers across multiple channels.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6.5",
      "activity_name": "Implement dry-run mode",
      "activity_description": "Print calculated config update to stdout without submitting.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A6.6",
      "activity_name": "Implement config update transaction submission",
      "activity_description": "Sign and submit config update transactions to orderer using provided signing identities.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6.7",
      "activity_name": "Error handling and validation",
      "activity_description": "Validate supported operations, provide error messages for unsupported ones, handle stacking operations.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A6.8",
      "activity_name": "Write unit tests for CLI components",
      "activity_description": "Test JSON parsing, operation logic, dry-run output.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6.9",
      "activity_name": "Write integration tests for CLI tool",
      "activity_description": "End-to-end test with a multi-channel test network.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6.10",
      "activity_name": "Update documentation and example command",
      "activity_description": "Provide example command and usage documentation.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A7.1",
      "activity_name": "Design API for OrdererGroup field setters",
      "activity_description": "Define SetMaxMessageCount, SetAbsoluteMaxBytes, SetPreferredMaxBytes, SetBatchTimeout, SetMaxChannels, SetConsensusType, SetConsensusState, and optional SetKafkaBrokers/SetEtcdRaftMetadata for U7.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A7.2",
      "activity_name": "Implement OrdererGroup field setters",
      "activity_description": "Add each setter function preserving existing values, implement EtcdRaftMetadata modifiers similar to AddConsenter/RemoveConsenter.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7.3",
      "activity_name": "Write unit tests for OrdererGroup setters",
      "activity_description": "Test each setter individually and in combination.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7.4",
      "activity_name": "Update examples for OrdererGroup updates",
      "activity_description": "Show both GetConfiguration/SetConfiguration and new setter methods.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A8.1",
      "activity_name": "Design API for MSP field setters",
      "activity_description": "Define all required setters (AddRootCert, RemoveRootCert, AddIntermediateCert, RemoveIntermediateCert, AddAdminCert, RemoveAdminCert, AddCRL, RemoveCRL, AddOUIdentifier, RemoveOUIdentifier, SetCryptoConfig, AddTLSRootCert, RemoveTLSRootCert, AddTLSIntermediateCert, RemoveTLSIntermediateCert, SetClientOUIdentifier, SetPeerOUIdentifier, SetAdminOUIdentifier, SetOrdererOUIdentifier, EnableNodeOUs, DisableNodeOUs) for OrdererOrgGroup, ApplicationOrgGroup, ConsortiumOrgGroup for U8.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A8.2",
      "activity_name": "Implement MSP field setters for three group types",
      "activity_description": "Add each setter function with certificate validation where needed, replace CreateMSPCRL usage.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A8.3",
      "activity_name": "Write unit tests for MSP setters",
      "activity_description": "Test each setter across three group types, including validation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8.4",
      "activity_name": "Update examples for MSP updates",
      "activity_description": "Show both GetMSP/SetMSP and new setter methods.",
      "most_likely_effort": 1
    }
  ],
  "reported_total": {
    "most_likely_effort": 57
  }
}

